insert into public.faqs (edition_id, question, answer, category, sort, published) select id, 'When and where is INSPIRE 2026?', 'Saturday 21 November 2026 at Lincoln Medical School, University of Lincoln. Session times will be published on the programme page once confirmed.', 'Conference', 0, true from _ed;
insert into public.faqs (edition_id, question, answer, category, sort, published) select id, 'Who is the conference for?', 'Medical students, aspiring clinician-researchers, early-career researchers, academic clinicians and healthcare innovators. You do not need research experience to attend.', 'Conference', 1, true from _ed;
insert into public.faqs (edition_id, question, answer, category, sort, published) select id, 'How do I register?', 'Registration details are published on the Conference 2026 page. The current registration status is always shown there.', 'Registration', 2, true from _ed;
insert into public.faqs (edition_id, question, answer, category, sort, published) select id, 'What do poster presenters need to do?', 'Accepted presenters should submit their poster by Friday 13 November 2026 and bring a printed copy to the conference. Landscape and portrait orientations are both accepted.', 'Research', 3, true from _ed;
insert into public.faqs (edition_id, question, answer, category, sort, published) select id, 'Do I need to choose workshops in advance?', 'Workshop allocation details will be confirmed by the conference team. You can explore all six workshops now and save the ones you are interested in to your agenda.', 'Workshops', 4, true from _ed;
insert into public.faqs (edition_id, question, answer, category, sort, published) select id, 'I have an access requirement. Who should I contact?', 'Please contact the team using the accessibility enquiry option on the contact page as early as possible, so arrangements can be made before the day.', 'Accessibility', 5, true from _ed;
